fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut max_streak = 1;
    let mut current_streak = 1;

    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            current_streak += 1;
        } else {
            if current_streak > max_streak {
                max_streak = current_streak;
            }
            current_streak = 1; // Reset current streak
        }
    }

    // Final check to update max_streak
    if current_streak > max_streak {
        max_streak = current_streak;
    }

    max_streak
}